import { useEffect } from 'react';

export const APP_BASE_URL = 'https://app.docshunt.ai';
export const APP_DEFAULT_OG_IMAGE_URL =
  'https://4691947d26a9c64d254186f138cdee17.cdn.bubble.io/cdn-cgi/image/w=,h=,f=auto,dpr=1,fit=contain/f1766369335570x680703495650288900/OGimge.png';

type SeoConfig = {
  title: string;
  description: string;
  canonicalUrl: string;
  imageUrl?: string;
  type?: 'website' | 'article';
};

const findMeta = (attribute: 'name' | 'property', value: string) => {
  return Array.from(document.head.querySelectorAll('meta')).find(
    (element) => element.getAttribute(attribute) === value
  ) as HTMLMetaElement | undefined;
};

const upsertMeta = (
  attribute: 'name' | 'property',
  value: string,
  content: string,
  restorers: Array<() => void>
) => {
  const existingTag = findMeta(attribute, value);
  const tag = existingTag ?? document.createElement('meta');
  const previousContent = existingTag?.getAttribute('content');

  tag.setAttribute(attribute, value);
  tag.setAttribute('content', content);

  if (!existingTag) {
    document.head.appendChild(tag);
  }

  restorers.push(() => {
    if (!existingTag) {
      tag.remove();
      return;
    }

    if (previousContent === null) {
      existingTag.removeAttribute('content');
      return;
    }

    existingTag.setAttribute('content', previousContent);
  });
};

const upsertCanonical = (href: string, restorers: Array<() => void>) => {
  const existingLink = document.head.querySelector(
    'link[rel="canonical"]'
  ) as HTMLLinkElement | null;
  const link = existingLink ?? document.createElement('link');
  const previousHref = existingLink?.getAttribute('href');

  link.setAttribute('rel', 'canonical');
  link.setAttribute('href', href);

  if (!existingLink) {
    document.head.appendChild(link);
  }

  restorers.push(() => {
    if (!existingLink) {
      link.remove();
      return;
    }

    if (previousHref === null) {
      existingLink.removeAttribute('href');
      return;
    }

    existingLink.setAttribute('href', previousHref);
  });
};

export const buildAppUrl = (pathname = '/') => {
  const baseUrl =
    typeof window === 'undefined' ? APP_BASE_URL : window.location.origin;

  return new URL(pathname, baseUrl).toString();
};

export const useDocumentSeo = ({
  title,
  description,
  canonicalUrl,
  imageUrl = APP_DEFAULT_OG_IMAGE_URL,
  type = 'website'
}: SeoConfig) => {
  useEffect(() => {
    const restorers: Array<() => void> = [];
    const previousTitle = document.title;

    document.title = title;

    upsertMeta('name', 'description', description, restorers);
    upsertMeta('property', 'og:type', type, restorers);
    upsertMeta('property', 'og:site_name', 'Docshunt', restorers);
    upsertMeta('property', 'og:url', canonicalUrl, restorers);
    upsertMeta('property', 'og:title', title, restorers);
    upsertMeta('property', 'og:description', description, restorers);
    upsertMeta('property', 'og:image', imageUrl, restorers);
    upsertMeta('name', 'twitter:card', 'summary_large_image', restorers);
    upsertMeta('name', 'twitter:url', canonicalUrl, restorers);
    upsertMeta('name', 'twitter:title', title, restorers);
    upsertMeta('name', 'twitter:description', description, restorers);
    upsertMeta('name', 'twitter:image', imageUrl, restorers);
    upsertCanonical(canonicalUrl, restorers);

    return () => {
      document.title = previousTitle;
      restorers.reverse().forEach((restore) => restore());
    };
  }, [canonicalUrl, description, imageUrl, title, type]);
};
